be32287a90746e731cce480eca4f40"}, {"content_key": "APBIO-FRQ-S-003", "version_id": "c4da3229-8d7a-4cf9-8738-68b62af20372", "version_num": 1, "status": "retired", "stimulus_image_path": "questions/apbio-frq-s-003/v2/f36f0e3337f393e1652e4d547eda5f2ac651fc740d56b13cc685aec8d73f8100.png", "full_version_hash": "06d67623f34c15d7fbfccda89c998b6d", "item_hash": "08a61d733a98ec7bd3ebc676342c5b96", "content_hash": "de4b2799ece91845d9c82f5404d3576d", "taxonomy_hash": "5a2e32068b6b7c0a593059b12ee41efd7d7a36a94e9c1b554deee2fe9be4e6dc", "criteria_hash": "38adaa3a10960f127dc3acaf479995b6", "label_hash": "dc0d7dea1a5f2c483bb1e0ea94b61f32", "assets_hash": "83d5062b7511b6456aa8d12d2b963367", "requirement_hash": "3c63e8e28d1db7adf37650f6490907e4"}]$baseline$::jsonb)
