do $guard$ begin
perform v.id from app.content_item_versions v join horizontal_baseline b on b.version_id=v.id order by v.id for update of v;
perform a.content_asset_metadata_id from app.content_asset_metadata a join horizontal_baseline b on b.version_id=a.content_item_version_id order by a.content_asset_metadata_id for update of a;
perform r.content_item_version_id from app.content_visual_requirements r join horizontal_baseline b on b.version_id=r.content_item_version_id order by r.content_item_version_id for update of r;

if (select count(*) from horizontal_baseline b join app.content_item_versions v on v.id=b.version_id)<>4 then raise exception 'Expected four bounded source/control versions'; end if;
if not exists(select 1 from app.profiles where user_id='f5a26c6b-3566-4d58-9e97-979fbb947564' and role='admin') then raise exception 'Owner profile guard'; end if;
if (select count(*) from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where v.id='bf317c96-1289-4803-b71f-b0aff4620844' and ci.content_key='APBIO-FRQ-S-003' and ci.status='published' and v.status='published')<>1 then raise exception 'Current published target drift'; end if;
if exists(select 1 from horizontal_baseline b join app.content_item_versions v on v.id=b.version_id join app.content_items ci on ci.id=v.content_item_id where
md5(to_jsonb(ci)::text)<>b.item_hash or md5((to_jsonb(v)-'stimulus_image_path'-'updated_at')::text)<>b.content_hash or app.taxonomy_relevant_hash(v.id)<>b.taxonomy_hash
or (select md5(coalesce(jsonb_agg(to_jsonb(f) order by to_jsonb(f)::text),'[]'::jsonb)::text) from app.frq_criteria f where f.content_item_version_id=v.id)<>b.criteria_hash
or (select md5(coalesce(jsonb_agg(to_jsonb(l) order by to_jsonb(l)::text),'[]'::jsonb)::text) from app.content_taxonomy_labels l where l.content_item_id=ci.id)<>b.label_hash
or (v.id<>'bf317c96-1289-4803-b71f-b0aff4620844'::uuid and md5(to_jsonb(v)::text)<>b.full_version_hash)
or (select md5(coalesce(jsonb_agg(to_jsonb(a) order by to_jsonb(a)::text),'[]'::jsonb)::text) from app.content_asset_metadata a where a.content_item_version_id=v.id and a.storage_path<>'questions/apbio-frq-s-003/v3/1e362c43a81c1f35ad88738751ccceae83c7e6b0c7a05d286b923fb2db737234.png')<>b.assets_hash
or (select md5(to_jsonb(r)::text) from app.content_visual_requirements r where r.content_item_version_id=v.id) is distinct from b.requirement_hash) then raise exception 'Source/scoring/taxonomy/labels/history/decisions drift'; end if;

if exists(select 1 from horizontal_baseline b join app.content_item_versions v on v.id=b.version_id where md5(to_jsonb(v)::text)<>b.full_version_hash) then raise exception 'Fresh full-version pin drift'; end if;
if exists(select 1 from app.content_asset_metadata where content_item_version_id='bf317c96-1289-4803-b71f-b0aff4620844' and storage_path='questions/apbio-frq-s-003/v3/1e362c43a81c1f35ad88738751ccceae83c7e6b0c7a05d286b923fb2db737234.png') then raise exception 'Horizontal metadata already exists'; end if;
if not exists(select 1 from storage.objects o join storage.buckets b on b.id=o.bucket_id where o.bucket_id='content-assets' and o.name='questions/apbio-frq-s-003/v3/1e362c43a81c1f35ad88738751ccceae83c7e6b0c7a05d286b923fb2db737234.png' and b.public=false and (o.metadata->>'size')::bigint=132560 and o.metadata->>'mimetype'='image/png') then raise exception 'Exact private horizontal object absent'; end if;
end $guard$;
insert into app.content_asset_metadata(content_item_version_id,storage_bucket,storage_path,alt_text,long_description,approved_by,approved_at)
values('bf317c96-1289-4803-b71f-b0aff4620844','content-assets','questions/apbio-frq-s-003/v3/1e362c43a81c1f35ad88738751ccceae83c7e6b0c7a05d286b923fb2db737234.png','Horizontal light-dependent photosynthesis schematic. A thylakoid membrane separates the lumen above from the stroma below; PSII, ETC, PSI, and ATP synthase are shown.','The thylakoid membrane is a horizontal band, with lumen above and stroma below. PSII means photosystem II, ETC means electron transport chain, and PSI means photosystem I. Light reaches PSII and PSI. Black electron arrows connect PSII to ETC, then to PSI and onward to NADP plus on the stroma side, where NADPH is formed. A blue proton arrow at ETC runs upward from stroma to lumen. A blue proton arrow through ATP synthase runs downward from lumen to stroma. NADP plus with H plus yields NADPH; ADP plus inorganic phosphate yields ATP, both on the stroma side. The diagram is schematic and does not specify molecule counts.','f5a26c6b-3566-4d58-9e97-979fbb947564',now());
