or (select md5(coalesce(jsonb_agg(to_jsonb(a) order by to_jsonb(a)::text),'[]'::jsonb)::text) from app.content_asset_metadata a where a.content_item_version_id=v.id and a.storage_path<>'questions/apbio-frq-s-003/v3/1e362c43a81c1f35ad88738751ccceae83c7e6b0c7a05d286b923fb2db737234.png')<>b.assets_hash
or (select md5(to_jsonb(r)::text) from app.content_visual_requirements r where r.content_item_version_id=v.id) is distinct from b.requirement_hash) then raise exception 'Source/scoring/taxonomy/labels/history/decisions drift'; end if;

if not exists(select 1 from app.content_item_versions v join app.content_asset_metadata a on a.content_item_version_id=v.id and a.storage_path=v.stimulus_image_path join app.content_visual_requirements r on r.content_item_version_id=v.id where v.id='bf317c96-1289-4803-b71f-b0aff4620844' and v.stimulus_image_path='questions/apbio-frq-s-003/v3/1e362c43a81c1f35ad88738751ccceae83c7e6b0c7a05d286b923fb2db737234.png' and a.storage_bucket='content-assets' and a.alt_text='Horizontal light-dependent photosynthesis schematic. A thylakoid membrane separates the lumen above from the stroma below; PSII, ETC, PSI, and ATP synthase are shown.' and a.long_description='The thylakoid membrane is a horizontal band, with lumen above and stroma below. PSII means photosystem II, ETC means electron transport chain, and PSI means photosystem I. Light reaches PSII and PSI. Black electron arrows connect PSII to ETC, then to PSI and onward to NADP plus on the stroma side, where NADPH is formed. A blue proton arrow at ETC runs upward from stroma to lumen. A blue proton arrow through ATP synthase runs downward from lumen to stroma. NADP plus with H plus yields NADPH; ADP plus inorganic phosphate yields ATP, both on the stroma side. The diagram is schematic and does not specify molecule counts.' and a.approved_by='f5a26c6b-3566-4d58-9e97-979fbb947564' and a.approved_at is not null and r.image_needed='yes' and r.image_approval='approved') then raise exception 'Horizontal delivery contract incomplete'; end if;
end $verify$;
update app.content_item_versions set stimulus_image_path='questions/apbio-frq-s-003/v2/f36f0e3337f393e1652e4d547eda5f2ac651fc740d56b13cc685aec8d73f8100.png' where id='bf317c96-1289-4803-b71f-b0aff4620844' and stimulus_image_path='questions/apbio-frq-s-003/v3/1e362c43a81c1f35ad88738751ccceae83c7e6b0c7a05d286b923fb2db737234.png';
