if not exists(select 1 from app.content_item_versions v join app.content_asset_metadata a on a.content_item_version_id=v.id and a.storage_path=v.stimulus_image_path where v.id='bf317c96-1289-4803-b71f-b0aff4620844' and v.stimulus_image_path='questions/apbio-frq-s-003/v2/f36f0e3337f393e1652e4d547eda5f2ac651fc740d56b13cc685aec8d73f8100.png' and a.approved_at is not null) then raise exception 'Prior tall image recovery failed'; end if;
